from pathlib import Path
from typing import Dict, Iterable, List


TABLE_ORDER = [
    "user",
    "health_info",
    "user_diet_preference",
    "diet_goal",
    "ingredient",
    "recipe",
    "recipe_ingredient",
    "user_recipe_collect",
    "diet_record",
    "diet_record_detail",
]


def write_sql_file(
    rows_by_table: Dict[str, List[Dict[str, object]]],
    output_path: Path,
    batch_size: int = 200,
) -> Path:
    output_path.parent.mkdir(parents=True, exist_ok=True)
    statements: List[str] = [
        "-- Generated by algorithm/training/data_generator",
        "SET NAMES utf8mb4;",
        "SET FOREIGN_KEY_CHECKS = 0;",
        "",
    ]
    for table_name in TABLE_ORDER:
        rows = rows_by_table.get(table_name, [])
        if not rows:
            continue
        statements.append(f"-- {table_name}: {len(rows)} rows")
        statements.extend(build_insert_sql(table_name, rows, batch_size=batch_size))
        statements.append("")
    statements.append("SET FOREIGN_KEY_CHECKS = 1;")
    output_path.write_text("\n".join(statements), encoding="utf-8")
    return output_path


def build_insert_sql(
    table_name: str,
    rows: Iterable[Dict[str, object]],
    batch_size: int = 200,
) -> List[str]:
    rows = list(rows)
    if not rows:
        return []
    columns = list(rows[0].keys())
    column_sql = ", ".join(f"`{column}`" for column in columns)
    safe_batch_size = max(1, int(batch_size))
    statements: List[str] = []
    for start in range(0, len(rows), safe_batch_size):
        batch_rows = rows[start : start + safe_batch_size]
        values_sql = ",\n".join(
            f"({', '.join(_to_sql_value(row[column]) for column in columns)})" for row in batch_rows
        )
        statements.append(f"INSERT INTO `{table_name}` ({column_sql}) VALUES\n{values_sql};")
    return statements


def _to_sql_value(value: object) -> str:
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "1" if value else "0"
    if isinstance(value, (int, float)):
        return str(value)
    text = str(value).replace("\\", "\\\\").replace("'", "\\'")
    return f"'{text}'"
